import fs from 'node:fs/promises';
const endpoint='https://mondayid-host.vercel.app/api/mcp';
async function rpc(id,method,params={}){const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json','accept':'application/json','MCP-Protocol-Version':'2025-03-26'},body:JSON.stringify({jsonrpc:'2.0',id,method,params})});const t=await r.text();let j;try{j=JSON.parse(t)}catch{j={parseError:true,text:t}}return {status:r.status,json:j};}
const init=await rpc(1,'initialize',{protocolVersion:'2025-03-26',capabilities:{},clientInfo:{name:'everything-compiler-proof',version:'1.0.0'}});
const list=await rpc(2,'tools/list',{});
const compiled=await rpc(3,'tools/call',{name:'compile_history',arguments:{}});
const value=compiled?.json?.result?.structuredContent;
const names=list?.json?.result?.tools?.map(x=>x.name)||[];
const ok=init.status===200 && names.includes('compile_history') && compiled.status===200 && value?.ok===true && value?.compiled?.projectRuntimeAuthority===false && value?.compiled?.totalValid>=40 && value?.compiled?.activeOrgans?.some(x=>x.organ==='MONDAY_WORK') && value?.compiled?.activeRoles?.some(x=>x.role==='JARVIS');
const proof={ok,marker:ok?'everything-compiler-live-ok':'everything-compiler-live-fail',endpoint,toolNames:names,totalValid:value?.compiled?.totalValid,uniqueEffects:value?.compiled?.uniqueEffects,compression:value?.compiled?.compression,activeOrgans:value?.delta?.activeOrgans,activeRoles:value?.delta?.activeRoles,externalGates:value?.delta?.externalGates};
await fs.writeFile('everything-compiler-live.json',JSON.stringify(proof));console.log(JSON.stringify(proof));if(!ok) process.exitCode=2;
